function calculateTotal(order: any): number {
  let total = 0;
  for (const item of order.items) {
    total += item.price * item.quantity;
  }
  return total;
}

class PaymentService {
  charge(card: any, amount: number) {
    if (!card || !card.number) throw new Error('Invalid card');
    if (!Number.isFinite(amount) || amount <= 0) throw new Error('Invalid amount');
    processPayment(card.number, amount);
  }
}

// Version A
function createUserA(data: any) {
  if (!data) data = {};
  const name = data.name || 'Unknown';
  const email = data.email || '';
  saveUser({ name, email });
}

// Version B
type NewUser = { name: string; email: string };
function validateNewUser(data: any): NewUser {
  if (!data || typeof data.name !== 'string') throw new Error('Invalid name');
  if (!data || typeof data.email !== 'string') throw new Error('Invalid email');
  return { name: data.name, email: data.email };
}
function createUserB(data: any) {
  const user = validateNewUser(data);
  saveUser(user);
}
